# area: gradual_any
# hypothesis: Inside a function scope, a method that reads a forward-referenced, decorator-wrapped function and a plain attribute set in the base __init__ should reveal int for the attribute, not int | None.
from collections.abc import Callable
from typing import TypeVar, reveal_type

T = TypeVar('T')


def deco(fn: Callable[[], T]) -> Callable[[], T]:
    def inner() -> T:
        return fn()
    return inner


class B:
    def __init__(self) -> None:
        self._foo: int = 1


def main() -> int:
    class C(B):
        def a(self) -> int:
            reveal_type(self._foo)
            return defer() + self._foo

    @deco
    def defer() -> int:
        return 3

    c = C()
    reveal_type(c.a())
    return c.a()


print(main())
reveal_type(deco)
